    fields.insert(2, FieldValue::Int(-42));
    fields.insert(3, FieldValue::UInt(9_999_999_999));
    fields.insert(4, FieldValue::Float(3.5));
    fields.insert(5, FieldValue::Text("hello café".to_string()));
