/** ⚠️ Container and schema errors preserve actual owned Value refusal identities. */
import { ValueError } from "../../🌱️value/⚠️refusal/🟦️.ts";
import { TextError } from "../../⚠️diagnostic/🚧️text-error/🟦️.ts";

export type PackErrorData =
  | Readonly<{kind: "BadMagic"}>
  | Readonly<{kind: "UnsupportedVersion"; major: number; minor: number}>
  | Readonly<{kind: "UnknownRequiredFlags"; flags: number}>
  | Readonly<{kind: "Truncated"; offset: bigint}>
  | Readonly<{kind: "ChecksumMismatch"; segment: string; offset: bigint}>
  | Readonly<{kind: "ContentHashMismatch"}>
  | Readonly<{kind: "LimitExceeded"; limit: string}>
  | Readonly<{kind: "RetainedMalformed" | "Malformed"; what: string; offset: bigint; detail: string}>
  | Readonly<{kind: "NonCanonical"; detail: string}>
  | Readonly<{kind: "UnsupportedCodec"; codec: number}>
  | Readonly<{kind: "ValueRefusal"; error: ValueError}>
  | Readonly<{kind: "TextRefusal"; error: TextError}>
  | Readonly<{kind: "Io"; message: string}>;

/** 🗨️ Renders the complete container error taxonomy without classifying message text. */
export function packErrorMessage(data: PackErrorData): string {
  switch (data.kind) {
    case "BadMagic": return "bad magic";
    case "UnsupportedVersion": return `unsupported version ${data.major}.${data.minor}`;
    case "UnknownRequiredFlags": return `unknown required feature bits 0x${data.flags.toString(16)}`;
    case "Truncated": return `truncated at offset ${data.offset}`;
    case "ChecksumMismatch": return `checksum mismatch in ${data.segment} at offset ${data.offset}`;
    case "ContentHashMismatch": return "content hash mismatch";
    case "LimitExceeded": return `limit exceeded: ${data.limit}`;
    case "RetainedMalformed": case "Malformed": return `malformed ${data.what} at offset ${data.offset}: ${data.detail}`;
    case "NonCanonical": return `non-canonical encoding: ${data.detail}`;
    case "UnsupportedCodec": return `unsupported codec ${data.codec}`;
    case "ValueRefusal": return `schema error: ${data.error.message}`;
    case "TextRefusal": return `schema error: ${data.error.toString()}`;
    case "Io": return `io error: ${data.message}`;
  }
}

/** 🪪️ Owns one explicit error payload and retains a typed refusal as its original cause. */
export class PackError extends Error {
  constructor(public readonly data: PackErrorData) {
    super(packErrorMessage(data), {cause: data.kind === "ValueRefusal" || data.kind === "TextRefusal" ? data.error : undefined});
    this.name = "PackError";
  }
  static fromValue(error: ValueError): PackError { return new PackError({kind: "ValueRefusal", error}); }
  static fromText(error: TextError): PackError { return new PackError({kind: "TextRefusal", error}); }
}

//! ⚠️ Canonical container and schema refusal identities below document composition.

use semio_framework_diagnostic::{FaultOrigin, TextError};
use semio_framework_value::{ValueError, ValueRefusalKind};

//#region 🔖️Errors
/// 🚨️ The one error type every `pack_*` public fn returns; never leaks `std::io::Error`.
#[derive(Debug, Clone, PartialEq)]
pub enum PackError {
    BadMagic,
    UnsupportedVersion { major: u16, minor: u16 },
    UnknownRequiredFlags(u32),
    Truncated(u64),
    ChecksumMismatch { segment: &'static str, offset: u64 },
    ContentHashMismatch,
    LimitExceeded(&'static str),
    RetainedMalformed { what: &'static str, offset: u64, detail: &'static str },
    Malformed { what: &'static str, offset: u64, detail: String },
    NonCanonical(&'static str),
    UnsupportedCodec(u8),
    ValueRefusal(ValueError),
    TextRefusal(TextError),
    Io(String),
}

impl PackError {
    /// 🧭️ Preserves typed schema refusals at the first-party container boundary.
    pub fn into_value_error(self) -> ValueError {
        match self {
            Self::ValueRefusal(error) => error,
            Self::TextRefusal(error) => ValueError::new(error.kind, error.message),
            error @ Self::LimitExceeded(_) => ValueError::new(ValueRefusalKind::WorkLimit, error.to_string()),
            error @ (Self::UnsupportedVersion { .. } | Self::UnknownRequiredFlags(_) | Self::UnsupportedCodec(_)) => ValueError::new(ValueRefusalKind::UnsupportedOwner, error.to_string()),
            error @ (Self::BadMagic | Self::Truncated(_) | Self::ChecksumMismatch { .. } | Self::ContentHashMismatch | Self::RetainedMalformed { .. } | Self::Malformed { .. } | Self::NonCanonical(_) | Self::Io(_)) => ValueError::new(ValueRefusalKind::InvalidValue, error.to_string()),
        }
    }
}

impl std::fmt::Display for PackError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::BadMagic => formatter.write_str("bad magic"),
            Self::UnsupportedVersion { major, minor } => write!(formatter, "unsupported version {major}.{minor}"),
            Self::UnknownRequiredFlags(flags) => write!(formatter, "unknown required feature bits {flags:#x}"),
            Self::Truncated(offset) => write!(formatter, "truncated at offset {offset}"),
            Self::ChecksumMismatch { segment, offset } => write!(formatter, "checksum mismatch in {segment} at offset {offset}"),
            Self::ContentHashMismatch => formatter.write_str("content hash mismatch"),
            Self::LimitExceeded(limit) => write!(formatter, "limit exceeded: {limit}"),
            Self::RetainedMalformed { what, offset, detail } => write!(formatter, "malformed {what} at offset {offset}: {detail}"),
            Self::Malformed { what, offset, detail } => write!(formatter, "malformed {what} at offset {offset}: {detail}"),
            Self::NonCanonical(detail) => write!(formatter, "non-canonical encoding: {detail}"),
            Self::UnsupportedCodec(codec) => write!(formatter, "unsupported codec {codec}"),
            Self::ValueRefusal(message) => write!(formatter, "schema error: {message}"),
            Self::TextRefusal(error) => write!(formatter, "schema error: {error}"),
            Self::Io(message) => write!(formatter, "io error: {message}"),
        }
    }
}

impl std::error::Error for PackError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self { Self::ValueRefusal(error) => Some(error), Self::TextRefusal(error) => Some(error), _ => None }
    }
}

impl From<ValueError> for PackError {
    fn from(error: ValueError) -> Self { Self::ValueRefusal(error) }
}

impl From<TextError> for PackError {
    fn from(error: TextError) -> Self { Self::TextRefusal(error) }
}

semio_framework_diagnostic::fault_from_error!(PackError, FaultOrigin::Module, "module.pack");

//#endregion 🔖️Errors
