impl std::error::Error for ArtifactAssemblyTransactionError {}

fn artifact_assembly_lock() -> &'static Mutex<()> {
    static LOCK: std::sync::OnceLock<Mutex<()>> = std::sync::OnceLock::new();
    LOCK.get_or_init(|| Mutex::new(()))
}

