                    ArtifactStoreOneItemPreparationStep::Progress(checkpoint) => Ok(ArtifactStoreOneItemAdvance::Progress(checkpoint)),
                    ArtifactStoreOneItemPreparationStep::Prepared(checkpoint) => {
