/// 🧹️ One retired value of an explicitly bounded store owner, charged exactly one page. `ManuallyDrop`
/// because every terminal shell under `ArtifactEnvelope` asserts that its owners left through a
/// cursor rather than through `Drop`.
///
/// 🎟️ The value is freed on the first positive grant; `debt` carries the part of its page charge that
/// did not fit the caller's grant and is reported in grant-sized instalments, so no turn exceeds its
/// grant and the close still reports exactly one page per value. A sub-page grant used to answer
/// `Pending { 0, 0 }` forever while `next_close_byte_demand` published 1 — the livelock that kept a
/// neutral 1-byte close of any app with a bounded config or draft lane from finishing
/// (ticket 26/09/19/SEMIO-TECH-PLAY-GRID-WITH-EVERY-APP, `📓️flow.md` §8).
struct BoundedArtifactValueRetirement<T> {
    value: std::mem::ManuallyDrop<Option<T>>,
    debt: usize,
}

impl<T> BoundedArtifactValueRetirement<T> {
    fn new(value: T) -> Self {
        Self { value: std::mem::ManuallyDrop::new(Some(value)), debt: 0 }
    }
}

impl<T: Send + 'static> ErasedSnapshotRetirement for BoundedArtifactValueRetirement<T> {
    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 || maximum_bytes == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if self.debt > 0 {
            let paid = self.debt.min(maximum_bytes);
            self.debt -= paid;
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: paid });
        }
        if let Some(value) = self.value.take() {
            drop(value);
            let paid = ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES.min(maximum_bytes);
            self.debt = ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES - paid;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: paid });
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.value.is_none() && self.debt == 0
    }
}

impl<T> Drop for BoundedArtifactValueRetirement<T> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.value.is_none() && self.debt == 0), "bounded artifact value retirement reached Drop before exact terminal emptiness");
    }
}

struct BoundedArtifactRetirementFactory<T>(PhantomData<fn() -> T>);

impl<T> BoundedArtifactRetirementFactory<T> {
    fn new() -> Self {
        Self(PhantomData)
    }
}

impl<T: Send + 'static> ArtifactOwnedValueRetirementFactory<T> for BoundedArtifactRetirementFactory<T> {
    fn retire_owned(&self, value: T) -> Box<dyn ErasedSnapshotRetirement> {
        Box::new(BoundedArtifactValueRetirement::new(value))
    }
}

impl<T: Send + Sync + 'static> SnapshotRetirementFactory<T> for BoundedArtifactRetirementFactory<T> {
    fn retire(&self, snapshot: Arc<T>) -> Box<dyn ErasedSnapshotRetirement> {
        Box::new(BoundedArtifactValueRetirement::new(snapshot))
    }
}

/// 🗃️ The exact one-page retirement catalogue for a store whose owner is the FRAMEWORK rather than a
/// plugin app: every factory releases one value per page-sized grant and the cursor disposer is the
/// store's own. `🔌️plugin`'s `bounded_config_store_owners`/`bounded_document_store_owners` are this
/// function — they delegate here rather than carrying a second copy — and
/// `ArtifactCodec::apply_ops_binary`'s throwaway reduction store installs it directly, which is the
/// only catalogue it can have: that thunk is monomorphized over `(P, Mutation)` alone, with no app
/// type in scope to ask `build_document_store_owners()` of (ticket 26/09/18 slices TC3e §7d, TC4).
pub fn bounded_artifact_store_owners<P, Mutation>() -> DocumentStoreOwners<P, Mutation>
where
    P: Clone + ToValue + FromValue + ArtifactPack + Send + Sync + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    DocumentStoreOwners::new(
        Arc::new(BoundedArtifactRetirementFactory::<P>::new()),
        Arc::new(BoundedArtifactRetirementFactory::<P>::new()),
        Arc::new(BoundedArtifactRetirementFactory::<Mutation>::new()),
        Box::new(ArtifactStoreCursorDisposer::<P, Mutation>::new()),
    )
}

/// 🧺️ Runs a throwaway reduction store's close cursor to exact terminal emptiness and forgets the
/// shell, so no codec thunk can reach `ArtifactStore`'s asserting `Drop` with a live owner. Shared by
/// [`ArtifactCodec::apply_ops_binary`] and [`replay_envelopes_onto_pair`].
fn close_codec_reduction_store<P, Mutation>(mut store: ArtifactStore<P, Mutation>) -> Result<(), VcsError>
where
    P: Clone + ToValue + FromValue + ArtifactPack + Send + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    let mut closed = Err(VcsError::ValidationFailed("artifact codec store did not reach terminal emptiness within its bounded close budget".into()));
    for _ in 0..ARTIFACT_CODEC_APPLY_CLOSE_MAXIMUM_STEPS {
        match store.close_owned_step(1, ARTIFACT_STORE_ONE_ITEM_MAXIMUM_BYTES) {
            Ok(SnapshotRetirementStep::Complete) => {
                closed = if store.close_owned_terminal_is_empty() { Ok(()) } else { Err(VcsError::ValidationFailed("artifact codec store reported close completion without terminal emptiness".into())) };
                break;
            }
            Ok(SnapshotRetirementStep::Pending { .. }) => continue,
            Ok(SnapshotRetirementStep::Blocked) => {
                closed = Err(VcsError::ValidationFailed("artifact codec store close is blocked by an outstanding snapshot read lease".into()));
                break;
            }
            Err(error) => {
                closed = Err(VcsError::ValidationFailed(error.into_message()));
                break;
            }
        }
    }
    let drop_ready = store.envelope_detached
        && store.current_detached
        && store.backbone.is_none()
        && store.dag.terminal_is_empty()
        && store.applied_edit_ids.is_empty()
        && store.redo_edit_ids.is_empty()
        && store.current_checkpoint_id.is_none()
        && store.local_actor_id.is_none()
        && store.revision_accumulator.applied.is_empty()
        && store.revision_accumulator.redo.is_empty()
        && store.tail_undo_cache.is_none()
        && store.snapshot_read_leases.terminal_is_empty()
        && store.displaced_retirements.terminal_is_empty()
        && store.owned_disposer.is_none()
        && store.owned_disposer_terminal
        && store.pending_report.edit_ids.is_none()
        && store.pending_report.messages.is_empty()
        && store.pending_report.outbound.is_empty()
        && store.pending_report.worst.is_none()
        && store.durable_group_root.is_none();
    std::mem::forget(store);
    closed?;
    if drop_ready {
        Ok(())
    } else {
        Err(VcsError::ValidationFailed("artifact codec store close left a live shallow-shell owner".into()))
    }
}

/// 📜️ Folds an [`crate::os_spr::encode_envelopes`] ledger stream onto one authoritative pair through
/// the SAME gate every replica folds a remote envelope through ([`ArtifactStore::ingest_remote`]):
/// causal order, history transitions (undo/redo/checkpoint), edit identity and conflict quarantine are
/// exactly a replica's, so the printed pair is the one any client holding that ledger prefix holds.
/// A quarantined conflict or an envelope left waiting on an unknown dependency refuses the fold, and a
/// raw-mutation apply (`apply_ops_binary`) is never a substitute: it mints new edit ids and drops every
/// transition. A ledger that changed effective inputs is judged once, as the history it folds to
/// ([`ArtifactStore::refuse_blocking_history`]) — never at the intermediate states its envelopes pass through, so a later
/// supersession heals an earlier one. This is how a hub materializes a Check In from its own ledger.
///
/// See `🌎️hub/🗿️artifact-authority/📌️check-in` and `db::artifact_ledger_tail`.
/// 📌️ The alternative a hub Check In materializes. It is the canonical trunk of `document_id`;
/// a viewer's checkout is local and never selects it.
pub fn canonical_check_in_line(document_id: &str) -> String {
    crate::os_spr::trunk_alternative_id(&ArtifactId(document_id.to_string()))
}

pub async fn replay_envelopes_onto_pair<P, Mutation>(pack: &[u8], spr: &[u8], envelopes: &[u8], owners: impl FnOnce() -> DocumentStoreOwners<P, Mutation>) -> Result<ArtifactPackFiles, VcsError>
where
    P: Clone + ToValue + FromValue + ArtifactPack + Send + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    if pack.is_empty() || spr.is_empty() {
        return Err(VcsError::Deserialize("replay-envelopes has no pack+spr baseline".into()));
    }
    let envelopes = crate::os_spr::decode_envelopes(envelopes).map_err(|error| VcsError::Deserialize(error.to_string()))?;
    let parsed = parse_document_pack::<P, Mutation>(pack, spr).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
    let mut envelope = parsed.into_envelope();
    let _canonical_line = canonical_check_in_line(&envelope.id);
    envelope.active_alternative_id = None;
    envelope.viewer_checkpoint_id = None;
    project_envelope_history(&mut envelope)?;
    let (applied, redo) = match &envelope.cursor {
        Some(cursor) => (cursor.applied_edit_ids.clone(), cursor.redo_edit_ids.clone()),
        None => (envelope.vcs.edits.iter().map(|edit| edit.id.clone()).collect(), crate::os_vcs::HistoryPageStack::new()),
    };
    envelope.cursor = Some(ArtifactCursor::new(applied, redo, envelope.cursor.as_ref().and_then(|cursor| cursor.checkpoint_id.clone())));
    let mut store = ArtifactStore::new(envelope).await?;
    store.install_document_store_owners_exact(owners());
    let baseline = store.supersessions().clone();
    let mut folded = Ok(());
    for envelope in envelopes {
        match store.ingest_remote(envelope).await {
            Ok(report) if report.accepted && report.conflict.is_none() => {}
            Ok(_) => {
                folded = Err(VcsError::ValidationFailed("replay-envelopes quarantined a ledger envelope as a conflict".into()));
                break;
            }
            Err(error) => {
                folded = Err(error);
                break;
            }
        }
    }
    if folded.is_ok() && !store.dag.pending_is_empty() {
        folded = Err(VcsError::ValidationFailed("replay-envelopes left a ledger envelope waiting on an unknown dependency".into()));
    }
    if folded.is_ok() && *store.supersessions() != baseline {
        folded = store.refuse_blocking_history();
    }
    let printed = match &folded {
        Ok(()) => print_document_pack(&store.envelope).await,
        Err(_) => Err(VcsError::ValidationFailed("replay-envelopes skipped print after a refused fold".into())),
    };
    let closed = close_codec_reduction_store(store);
    folded?;
    closed?;
    printed
}
//#endregion 🗃️BoundedArtifactStoreOwners

impl ArtifactCodec {
    /// 🏗️ Monomorphizes three non-capturing bridge functions for `(P, Mutation)` — each a
    /// genuine zero-sized `fn` item, coercible to a bare `fn` pointer — and pairs them with `schema`/
    /// `P::EXTENSION`. One call site per document kind (`register_document_codec_for_app`).
    ///
    /// 🚫️async: E4 fn-pointer erasure-table thunk — VALUE goes into `ArtifactCodec::compile_dsl`
    /// (`fn` slot, unnameable if `async fn`); wraps its real async body in `Box::pin` per R1(ii).
    ///
    /// 🚫️async: E4 fn-pointer erasure-table thunk — see `compile_dsl_impl`'s tag above.
    ///
    /// 🚫️async: E4 fn-pointer erasure-table thunk — see `compile_dsl_impl`'s tag above.
    ///
    /// 🚫️async: E4 fn-pointer erasure-table thunk — see `compile_dsl_impl`'s tag above.
    ///
    /// 🚫️async: E4 fn-pointer erasure-table thunk — see `compile_dsl_impl`'s tag above.
    ///
    /// 🌀️ `schema_hash` is async; `Option::map`'s closure is sync (R10 shape 1), so it's
    /// written as an explicit match instead.
    /// 🪶️ Constructs a codec with a required, actual relational snapshot implementation.
    pub fn of<P, Mutation>(schema: impl Into<String>) -> Self
    where
        P: Clone + PartialEq + ToValue + FromValue + ArtifactDsl + ArtifactPack + ArtifactSqliteSnapshot + Send + Sync + 'static,
        Mutation: self::Mutation<P> + PartialEq + ToValue + FromValue + OpText + OpBinary + Send + Sync + 'static,
    {
        let mut codec = Self::bare::<P, Mutation>(schema);
        codec.snapshot_sqlite = Some(P::sqlite_codec());
        codec
    }

    /// 📦️ Constructs a native document codec from its owner's declared capabilities.
    pub fn bare<P, Mutation>(schema: impl Into<String>) -> Self
    where
        P: Clone + PartialEq + ToValue + FromValue + ArtifactDsl + ArtifactPack + Send + Sync + 'static,
        Mutation: self::Mutation<P> + PartialEq + ToValue + FromValue + OpText + OpBinary + Send + Sync + 'static,
    {
        /// 🕰️`'static`, not `'a`. These items are coerced to `for<'a> fn(..) -> ..` pointers, so a
        /// `P: 'a` bound would have to hold for EVERY lifetime — which is `'static` by another name,
        /// and which the compiler cannot infer from the bound as written ("one type is more general
        /// than the other"). The enclosing `of<P, Mutation>` already requires `'static` of both, so
        /// saying it here costs nothing and lets the coercion succeed.
        fn compile_dsl_impl<'a, P, Mutation>(dsl: &'a str, ops: &'a str) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<(ArtifactPackFiles, String), VcsError>> + Send + 'a>>
        where
            P: Clone + ArtifactDsl + ArtifactPack + Send + Sync + 'static,
            Mutation: OpText + OpBinary + self::Mutation<P> + Send + Sync + 'static,
        {
            Box::pin(async move {
                let parsed: ParsedDocumentText<P, Mutation> = parse_document_text(dsl, ops).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
                let envelope = parsed.into_envelope();
                let pack_files = print_document_pack(&envelope).await;
                let dsl_mirror = envelope.vcs.initial_snapshot.print_dsl();
                envelope.retire_unadopted();
                Ok((pack_files?, dsl_mirror))
            })
        }

        /// 🕰️`'static`, not `'a`. These items are coerced to `for<'a> fn(..) -> ..` pointers, so a
        /// `P: 'a` bound would have to hold for EVERY lifetime — which is `'static` by another name,
        /// and which the compiler cannot infer from the bound as written ("one type is more general
        /// than the other"). The enclosing `of<P, Mutation>` already requires `'static` of both, so
        /// saying it here costs nothing and lets the coercion succeed.
        fn print_mirror_impl<'a, P, Mutation>(pack: &'a [u8], spr: &'a [u8]) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<ArtifactTextFiles, VcsError>> + Send + 'a>>
        where
            P: Clone + ArtifactDsl + ArtifactPack + Send + Sync + 'static,
            Mutation: OpText + OpBinary + self::Mutation<P> + Send + Sync + 'static,
        {
            Box::pin(async move {
                let parsed: ParsedDocumentText<P, Mutation> = parse_document_pack(pack, spr).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
                let envelope = parsed.into_envelope();
                let mirror = print_document_text(&envelope).await;
                envelope.retire_unadopted();
                mirror
            })
        }

        /// 🎯️ `encode_ops_vec(&[])` is a NON-empty framed header, not a zero-length byte
        /// slice — the empty-batch fast path must key off the DECODED mutation count, or an
        /// empty gesture builds a store, hits `EmptyApply`, and (before TC5) aborted in Drop.
        ///
        /// 🛂️ The throwaway reduction store gets the framework's own bounded owner
        /// catalogue. `ArtifactStore::new` installs NONE, and an uninstalled store cannot
        /// retire: the close cursor below answers `artifact store has no owner-supplied
        /// bounded disposer` for the first nonempty batch through a LINKED Rust codec —
        /// the path stdio and gis take on a hub. The guest twin
        /// (`plugin_runtime::artifact_app_apply_ops`) installs the APP's own catalogue
        /// there, which this thunk has no app type to ask for; the framework catalogue is
        /// the exact equivalent for a store that lives only for one reduction (ticket
        /// 26/09/18 slices TC3e §7d, TC4 §2).
        ///
        /// 🗄️ Never `?` while `store` is live: `ArtifactStore`'s Drop asserts a terminal
        /// shallow shell, so an early return here aborts the process instead of reporting the
        /// fault. Capture every fallible step as a value, run the close cursor, forget the
        /// store, THEN propagate — the guest twin does the same (ticket 26/09/18 TC3e/TC5).
        fn apply_ops_binary_impl<'a, P, Mutation>(pack: &'a [u8], spr: &'a [u8], ops_vec: &'a [u8]) -> ArtifactCodecApplyFuture<'a>
        where
            P: Clone + ToValue + FromValue + ArtifactDsl + ArtifactPack + Send + Sync + 'static,
            Mutation: ToValue + FromValue + OpText + OpBinary + self::Mutation<P> + Send + Sync + 'static,
        {
            Box::pin(async move {
                let mutations: Vec<Mutation> = if ops_vec.is_empty() {
                    Vec::new()
                } else {
                    let op_blobs = crate::os_spr::decode_ops_vec(ops_vec).map_err(|error| VcsError::Deserialize(error.to_string()))?;
                    let mut decoded = Vec::with_capacity(op_blobs.len());
                    for bytes in &op_blobs {
                        decoded.push(Mutation::decode_op(bytes).map_err(|error| VcsError::Deserialize(error.to_string()))?);
                    }
                    decoded
                };
                if mutations.is_empty() {
                    if pack.is_empty() && spr.is_empty() {
                        return Ok((Vec::new(), Vec::new(), String::new()));
                    }
                    let parsed = parse_document_pack::<P, Mutation>(pack, spr).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
                    let envelope = parsed.into_envelope();
                    let printed = print_document_pack(&envelope).await;
                    envelope.retire_unadopted();
                    let files = printed?;
                    return Ok((files.pack, files.spr, files.ops));
                }
                let mut store = if pack.is_empty() && spr.is_empty() {
                    return Err(VcsError::Deserialize("apply_ops_binary: lane has no pack+spr baseline".into()));
                } else {
                    let parsed = parse_document_pack::<P, Mutation>(pack, spr).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
                    let mut envelope = parsed.into_envelope();
                    let (applied, redo) = match &envelope.cursor {
                        Some(cursor) => (cursor.applied_edit_ids.clone(), cursor.redo_edit_ids.clone()),
                        None => (envelope.vcs.edits.iter().map(|edit| edit.id.clone()).collect(), crate::os_vcs::HistoryPageStack::new()),
                    };
                    envelope.cursor = Some(ArtifactCursor::new(applied, redo, envelope.cursor.as_ref().and_then(|cursor| cursor.checkpoint_id.clone())));
                    let mut store = ArtifactStore::new(envelope).await?;
                    store.install_document_store_owners_exact(bounded_artifact_store_owners::<P, Mutation>());
                    store
                };
                let applied = store.dispatch_apply_exact(mutations, None).await;
                let printed = match &applied {
                    Ok(_) => print_document_pack(&store.envelope).await,
                    Err(_) => Err(VcsError::ValidationFailed("artifact codec apply skipped print after a failed reduction".into())),
                };
                let closed = close_codec_reduction_store(store);
                applied?;
                closed?;
                let files = printed?;
                Ok((files.pack, files.spr, files.ops))
            })
        }

        fn replay_envelopes_impl<'a, P, Mutation>(pack: &'a [u8], spr: &'a [u8], envelopes: &'a [u8]) -> ArtifactCodecApplyFuture<'a>
        where
            P: Clone + ToValue + FromValue + ArtifactDsl + ArtifactPack + Send + Sync + 'static,
            Mutation: Clone + ToValue + FromValue + OpText + OpBinary + self::Mutation<P> + Send + Sync + 'static,
        {
            Box::pin(async move {
                let files = replay_envelopes_onto_pair::<P, Mutation>(pack, spr, envelopes, bounded_artifact_store_owners::<P, Mutation>).await?;
                Ok((files.pack, files.spr, files.ops))
            })
        }

        fn edit_text_from_envelope_impl<'a, P, Mutation>(envelope: &'a crate::os_spr::MutationEnvelope) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<String, VcsError>> + 'a>>
        where
            Mutation: OpText + OpBinary,
        {
            Box::pin(async move {
                let edit = edit_from_operation_envelope::<Mutation>(envelope).await?;
                print_edit_lines(&edit).await
            })
        }


        Self {
            schema: schema.into(),
            extension: P::EXTENSION,
            snapshot_sqlite: P::sqlite_snapshot_codec(),
            pack_schema_hash: match P::record_spec() {
                Some(spec) => crate::os_pack::schema_hash(&spec),
                None => [0u8; 32],
            },
            compile_dsl: compile_dsl_impl::<P, Mutation>,
            print_mirror: print_mirror_impl::<P, Mutation>,
            edit_text_from_envelope: edit_text_from_envelope_impl::<P, Mutation>,
            apply_ops_binary: apply_ops_binary_impl::<P, Mutation>,
            replay_envelopes: replay_envelopes_impl::<P, Mutation>,
        }
    }
}

static DOCUMENT_CODEC_REGISTRY: std::sync::OnceLock<std::sync::RwLock<BTreeMap<String, ArtifactCodec>>> = std::sync::OnceLock::new();

fn document_codec_registry() -> &'static std::sync::RwLock<BTreeMap<String, ArtifactCodec>> {
    DOCUMENT_CODEC_REGISTRY.get_or_init(|| std::sync::RwLock::new(BTreeMap::new()))
}

/// ⚠️ A document schema already has a codec owner. The established codec is never replaced.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DocumentCodecRegistryConflict {
    pub schema: String,
}

/// ⚠️ Document-codec registration cannot replace an owner or use an unavailable registry.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DocumentCodecRegistryError {
    Conflict(DocumentCodecRegistryConflict),
    Unavailable,
}

impl std::fmt::Display for DocumentCodecRegistryError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Conflict(error) => write!(formatter, "document codec registration conflicts for schema {}", error.schema),
            Self::Unavailable => formatter.write_str("document codec registry unavailable"),
        }
    }
}

impl std::error::Error for DocumentCodecRegistryError {}

fn same_document_codec(left: &ArtifactCodec, right: &ArtifactCodec) -> bool {
    left.schema == right.schema
        && left.extension == right.extension
        && match (left.snapshot_sqlite.as_ref(), right.snapshot_sqlite.as_ref()) {
            (Some(left), Some(right)) => left.identical_to(right),
            (None, None) => true,
            _ => false,
        }
        && left.pack_schema_hash == right.pack_schema_hash
        && std::ptr::fn_addr_eq(left.compile_dsl, right.compile_dsl)
        && std::ptr::fn_addr_eq(left.print_mirror, right.print_mirror)
        && std::ptr::fn_addr_eq(left.edit_text_from_envelope, right.edit_text_from_envelope)
        && std::ptr::fn_addr_eq(left.apply_ops_binary, right.apply_ops_binary)
        && std::ptr::fn_addr_eq(left.replay_envelopes, right.replay_envelopes)
}

fn validate_document_codecs(registry: &BTreeMap<String, ArtifactCodec>, codecs: &[ArtifactCodec]) -> Result<(), DocumentCodecRegistryError> {
    let mut proposed: BTreeMap<&str, &ArtifactCodec> = BTreeMap::new();
    for codec in codecs {
        match proposed.get(codec.schema.as_str()) {
            Some(existing) if same_document_codec(existing, codec) => {}
            Some(_) => return Err(DocumentCodecRegistryError::Conflict(DocumentCodecRegistryConflict { schema: codec.schema.clone() })),
            None => {
                proposed.insert(codec.schema.as_str(), codec);
            }
        }
    }
    for (schema, codec) in proposed {
        match registry.get(schema) {
            Some(existing) if same_document_codec(existing, codec) => {}
            Some(_) => return Err(DocumentCodecRegistryError::Conflict(DocumentCodecRegistryConflict { schema: schema.to_string() })),
            None => {}
        }
    }
    Ok(())
}

/// 🔬️ Verifies document codecs against all established schemas without mutating the registry.
#[must_use]
pub async fn preflight_document_codecs(codecs: &[ArtifactCodec]) -> Result<(), DocumentCodecRegistryError> {
    let assembly = begin_artifact_assembly().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    preflight_document_codecs_in_assembly(&assembly, codecs)
}

/// 🔬️ Verifies document codecs while one artifact assembly owns the shared publication barrier.
#[must_use]
pub fn preflight_document_codecs_in_assembly(_assembly: &ArtifactAssemblyTransaction, codecs: &[ArtifactCodec]) -> Result<(), DocumentCodecRegistryError> {
    let registry = document_codec_registry().read().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    validate_document_codecs(&registry, codecs)
}

/// 📝️ Registers one schema codec exactly once. Collisions fail deterministically before any
/// replacement can occur, so registration order never changes decoding behavior.
#[must_use]
pub fn register_document_codec(codec: ArtifactCodec) -> Result<(), DocumentCodecRegistryError> {
    register_document_codecs(vec![codec])
}

/// 📝️ Registers document codecs only when every descriptor and executable is conflict-free.
#[must_use]
pub fn register_document_codecs(codecs: Vec<ArtifactCodec>) -> Result<(), DocumentCodecRegistryError> {
    let assembly = begin_artifact_assembly().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    register_document_codecs_in_assembly(&assembly, codecs)
}

/// 📝️ Publishes preflighted document codecs while one artifact assembly owns the shared barrier.
#[must_use]
pub fn register_document_codecs_in_assembly(_assembly: &ArtifactAssemblyTransaction, codecs: Vec<ArtifactCodec>) -> Result<(), DocumentCodecRegistryError> {
    let mut registry = document_codec_registry().write().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    validate_document_codecs(&registry, &codecs)?;
    for codec in codecs {
        if !registry.contains_key(&codec.schema) {
            registry.insert(codec.schema.clone(), codec);
        }
    }
    Ok(())
}

/// 🔎️ Looks up the codec registered for `schema`, if any.
#[must_use]
pub async fn document_codec(schema: &str) -> Result<Option<ArtifactCodec>, DocumentCodecRegistryError> {
    let registry = document_codec_registry().read().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    Ok(registry.get(schema).cloned())
}

/// 🧬️ A component codec answer still in flight. `Send` natively, where document owners run on
/// the shared worker pool; the browser's single isolate needs no `Send`.
#[cfg(not(target_arch = "wasm32"))]
pub type ComponentDocumentCodecFuture<'a, T> = std::pin::Pin<Box<dyn std::future::Future<Output = Result<T, VcsError>> + Send + 'a>>;

#[cfg(target_arch = "wasm32")]
pub type ComponentDocumentCodecFuture<'a, T> = std::pin::Pin<Box<dyn std::future::Future<Output = Result<T, VcsError>> + 'a>>;

/// 🧬️ One document kind's codec as the COMPONENT that owns the kind answers it — the
/// `world actor` `codec` interface (ticket 26/09/18 slice TC3b) — installed by the host that mounted
/// that component. A process that links no Rust codec for a kind identifies and validates its documents
/// through this, exactly as the hub's trusted catalog does for a package it links no codec for
/// (`🌎️hub/🗿️artifact-authority/🔏️trusted-catalog`'s `VerifiedNativeArtifactCodec`: its linked `codec`,
/// else its component `guest`).
pub trait ComponentDocumentCodec: Send + Sync {
    /// 🏷️ The document schema the component owns.
    fn schema(&self) -> &str;
    /// 🧬️ `codec.pack-schema-hash`: the kind's structural snapshot fingerprint.
    fn pack_schema_hash(&self) -> ComponentDocumentCodecFuture<'_, [u8; 32]>;
    /// 📥️ `codec.print-mirror`: the pair's text mirror, which is also its validation fence.
    fn print_mirror<'a>(&'a self, pack: &'a [u8], spr: &'a [u8]) -> ComponentDocumentCodecFuture<'a, ArtifactTextFiles>;
}

/// 🧭️ The one codec a document owner resolves for a schema: the Rust codec this binary links
/// when it links one, else the component codec installed for the mounted component that owns the kind.
#[derive(Clone)]
pub enum DocumentKindCodec {
    Linked(ArtifactCodec),
    Component(Arc<dyn ComponentDocumentCodec>),
}

impl DocumentKindCodec {
    /// 🧬️ The kind's structural snapshot fingerprint.
    pub async fn pack_schema_hash(&self) -> Result<[u8; 32], VcsError> {
        match self {
            Self::Linked(codec) => Ok(codec.pack_schema_hash),
            Self::Component(codec) => codec.pack_schema_hash().await,
        }
    }

    /// 📥️ The pair's text mirror; an `Err` means the pair is not a document of this kind.
    pub async fn print_mirror(&self, pack: &[u8], spr: &[u8]) -> Result<ArtifactTextFiles, VcsError> {
        match self {
            Self::Linked(codec) => (codec.print_mirror)(pack, spr).await,
            Self::Component(codec) => codec.print_mirror(pack, spr).await,
        }
    }
}

static COMPONENT_DOCUMENT_CODEC_REGISTRY: std::sync::OnceLock<std::sync::RwLock<BTreeMap<String, Arc<dyn ComponentDocumentCodec>>>> = std::sync::OnceLock::new();

fn component_document_codec_registry() -> &'static std::sync::RwLock<BTreeMap<String, Arc<dyn ComponentDocumentCodec>>> {
    COMPONENT_DOCUMENT_CODEC_REGISTRY.get_or_init(|| std::sync::RwLock::new(BTreeMap::new()))
}

/// 📝️ Installs a mounted component's codec for the schema it owns. A later mount of that kind's
/// owner replaces an earlier one: in this process the component a host mounted IS the kind's owner.
#[must_use]
pub fn register_component_document_codec(codec: Arc<dyn ComponentDocumentCodec>) -> Result<(), DocumentCodecRegistryError> {
    let mut registry = component_document_codec_registry().write().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    registry.insert(codec.schema().to_string(), codec);
    Ok(())
}

/// 🔎️ Resolves `schema` to the one codec a document owner uses — see [`DocumentKindCodec`].
#[must_use]
pub async fn document_kind_codec(schema: &str) -> Result<Option<DocumentKindCodec>, DocumentCodecRegistryError> {
    if let Some(codec) = document_codec(schema).await? {
        return Ok(Some(DocumentKindCodec::Linked(codec)));
    }
    let registry = component_document_codec_registry().read().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    Ok(registry.get(schema).cloned().map(DocumentKindCodec::Component))
}

/// 📜️ Reads the document schema id from an encoded `.spr` history log.
pub async fn lane_schema_from_spr(spr: &[u8]) -> Option<String> {
    if spr.is_empty() {
        return None;
    }
    crate::os_spr::decode_history(spr, &crate::os_spr::DecodeOptions::default()).await.ok().map(|log| log.schema).filter(|schema| !schema.is_empty())
}
//#endregion 🔖️CodecRegistry

//#region 🔖️DialectMigration
/// 🧬️ One registered lossy/lossless pack-bytes transform between two dialects of the SAME
/// artifact kind (`from.artifact_kind == to.artifact_kind` is a convention this registry doesn't
/// itself enforce — callers key by the exact `(from, to)` pair they registered). `migrate_pack` is
/// a bare `fn` pointer (same non-capturing-bridge-function shape `ArtifactCodec::of` already uses
/// for `compile_dsl`/`print_mirror`/etc above) so a migration can be a plain top-level fn with zero
/// closure-capture ceremony. Additive-only: nothing in `ArtifactCodec`/`document_codec`/
/// `ArtifactStore::dispatch` reads this registry yet — see `26/08/10` D4 evolution slice scope note.
#[derive(Clone)]
pub struct DialectMigration {
    pub from: crate::os_io::ArtifactDialect,
    pub to: crate::os_io::ArtifactDialect,
    pub lossless: bool,
    pub migrate_pack: fn(&[u8]) -> Result<Vec<u8>, String>,
}

static DIALECT_MIGRATION_REGISTRY: std::sync::OnceLock<std::sync::RwLock<BTreeMap<(crate::os_io::ArtifactDialect, crate::os_io::ArtifactDialect), DialectMigration>>> = std::sync::OnceLock::new();

fn dialect_migration_registry() -> &'static std::sync::RwLock<BTreeMap<(crate::os_io::ArtifactDialect, crate::os_io::ArtifactDialect), DialectMigration>> {
    DIALECT_MIGRATION_REGISTRY.get_or_init(|| std::sync::RwLock::new(BTreeMap::new()))
}

/// ⚠️ Dialect-migration registration cannot overwrite an owner or cross artifact kinds.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DialectMigrationRegistryError {
    CrossArtifactKind { from: crate::os_io::ArtifactDialect, to: crate::os_io::ArtifactDialect },
    Conflict { from: crate::os_io::ArtifactDialect, to: crate::os_io::ArtifactDialect },
    Unavailable,
}

impl std::fmt::Display for DialectMigrationRegistryError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::CrossArtifactKind { from, to } => write!(f, "dialect migration crosses artifact kinds from {from:?} to {to:?}"),
            Self::Conflict { from, to } => write!(f, "dialect migration conflict from {from:?} to {to:?}"),
            Self::Unavailable => write!(f, "dialect migration registry unavailable"),
        }
    }
}
impl std::error::Error for DialectMigrationRegistryError {}

/// 🚫️ A migration was unavailable or the registered executable rejected its input.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DialectMigrationError {
    Missing { from: crate::os_io::ArtifactDialect, to: crate::os_io::ArtifactDialect },
    Unavailable,
    Rejected(String),
}

fn same_dialect_migration(left: &DialectMigration, right: &DialectMigration) -> bool {
    left.from == right.from && left.to == right.to && left.lossless == right.lossless && std::ptr::fn_addr_eq(left.migrate_pack, right.migrate_pack)
}

fn validate_dialect_migrations(registry: &BTreeMap<(crate::os_io::ArtifactDialect, crate::os_io::ArtifactDialect), DialectMigration>, migrations: &[DialectMigration]) -> Result<(), DialectMigrationRegistryError> {
    let mut proposed: BTreeMap<(crate::os_io::ArtifactDialect, crate::os_io::ArtifactDialect), &DialectMigration> = BTreeMap::new();
    for migration in migrations {
        if migration.from.artifact_kind != migration.to.artifact_kind {
            return Err(DialectMigrationRegistryError::CrossArtifactKind { from: migration.from.clone(), to: migration.to.clone() });
        }
        let key = (migration.from.clone(), migration.to.clone());
        match proposed.get(&key) {
            Some(existing) if same_dialect_migration(existing, migration) => {}
            Some(_) => return Err(DialectMigrationRegistryError::Conflict { from: key.0, to: key.1 }),
            None => {
                proposed.insert(key, migration);
            }
        }
    }
    for (key, migration) in proposed {
        match registry.get(&key) {
            Some(existing) if same_dialect_migration(existing, migration) => {}
            Some(_) => return Err(DialectMigrationRegistryError::Conflict { from: key.0, to: key.1 }),
            None => {}
        }
    }
    Ok(())
}

/// 🔬️ Verifies a migration set against established dialect pairs without mutation.
#[must_use]
pub async fn preflight_dialect_migrations(migrations: &[DialectMigration]) -> Result<(), DialectMigrationRegistryError> {
    let assembly = begin_artifact_assembly().map_err(|_| DialectMigrationRegistryError::Unavailable)?;
    preflight_dialect_migrations_in_assembly(&assembly, migrations).await
}

/// 🔬️ Verifies migrations while one artifact assembly owns the shared publication barrier.
#[must_use]
pub async fn preflight_dialect_migrations_in_assembly(_assembly: &ArtifactAssemblyTransaction, migrations: &[DialectMigration]) -> Result<(), DialectMigrationRegistryError> {
    let registry = dialect_migration_registry().read().map_err(|_| DialectMigrationRegistryError::Unavailable)?;
    validate_dialect_migrations(&registry, migrations)
}

/// 📝️ Registers a migration only when its full descriptor and executable identity match.
#[must_use]
pub fn register_dialect_migration(migration: DialectMigration) -> Result<(), DialectMigrationRegistryError> {
    register_dialect_migrations(vec![migration])
}

/// 📝️ Registers migrations only when every candidate pair is conflict-free.
#[must_use]
pub fn register_dialect_migrations(migrations: Vec<DialectMigration>) -> Result<(), DialectMigrationRegistryError> {
    let assembly = begin_artifact_assembly().map_err(|_| DialectMigrationRegistryError::Unavailable)?;
    register_dialect_migrations_in_assembly(&assembly, migrations)
}

/// 📝️ Publishes preflighted migrations while one artifact assembly owns the shared barrier.
#[must_use]
pub fn register_dialect_migrations_in_assembly(_assembly: &ArtifactAssemblyTransaction, migrations: Vec<DialectMigration>) -> Result<(), DialectMigrationRegistryError> {
    let mut registry = dialect_migration_registry().write().map_err(|_| DialectMigrationRegistryError::Unavailable)?;
    validate_dialect_migrations(&registry, &migrations)?;
    for migration in migrations {
        let key = (migration.from.clone(), migration.to.clone());
        registry.entry(key).or_insert(migration);
    }
    Ok(())
}

/// 🔁️ Looks up the exact `(from, to)` migration and runs its `migrate_pack` over
/// `pack_bytes`, or a clear `Err` naming both dialect coordinates when none is registered.
#[must_use]
pub async fn migrate_document(from: &crate::os_io::ArtifactDialect, to: &crate::os_io::ArtifactDialect, pack_bytes: &[u8]) -> Result<Vec<u8>, DialectMigrationError> {
    let registry = dialect_migration_registry().read().map_err(|_| DialectMigrationError::Unavailable)?;
    let migration = registry.get(&(from.clone(), to.clone())).ok_or_else(|| DialectMigrationError::Missing { from: from.clone(), to: to.clone() })?;
    (migration.migrate_pack)(pack_bytes).map_err(DialectMigrationError::Rejected)
}

/// 🧷️ All writable store registries held before an artifact assembly can publish anything.
pub struct ArtifactAssemblyStoreRegistryGuards<'assembly> {
    document_codecs: std::sync::RwLockWriteGuard<'static, BTreeMap<String, ArtifactCodec>>,
    dialect_migrations: std::sync::RwLockWriteGuard<'static, BTreeMap<(crate::os_io::ArtifactDialect, crate::os_io::ArtifactDialect), DialectMigration>>,
    _assembly: &'assembly ArtifactAssemblyTransaction,
}

/// 🚫️ A staged store registry assembly cannot be preflighted or committed.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ArtifactAssemblyStoreRegistryError {
    DocumentCodec(DocumentCodecRegistryError),
    DialectMigration(DialectMigrationRegistryError),
}

impl std::fmt::Display for ArtifactAssemblyStoreRegistryError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::DocumentCodec(error) => error.fmt(formatter),
            Self::DialectMigration(error) => error.fmt(formatter),
        }
    }
}

impl std::error::Error for ArtifactAssemblyStoreRegistryError {}

/// 🧷️ Acquires every store registry write lock before an assembly validates or mutates state.
#[must_use]
pub fn acquire_artifact_assembly_store_registry_guards<'assembly>(assembly: &'assembly ArtifactAssemblyTransaction) -> Result<ArtifactAssemblyStoreRegistryGuards<'assembly>, ArtifactAssemblyStoreRegistryError> {
    let document_codecs = document_codec_registry().write().map_err(|_| ArtifactAssemblyStoreRegistryError::DocumentCodec(DocumentCodecRegistryError::Unavailable))?;
    let dialect_migrations = dialect_migration_registry().write().map_err(|_| ArtifactAssemblyStoreRegistryError::DialectMigration(DialectMigrationRegistryError::Unavailable))?;
    Ok(ArtifactAssemblyStoreRegistryGuards { document_codecs, dialect_migrations, _assembly: assembly })
}

/// 🔬️ Verifies all staged store rows while every affected write lock is already held.
#[must_use]
pub fn preflight_artifact_assembly_store_registry_guards(guards: &ArtifactAssemblyStoreRegistryGuards<'_>, document_codecs: &[ArtifactCodec], dialect_migrations: &[DialectMigration]) -> Result<(), ArtifactAssemblyStoreRegistryError> {
    validate_document_codecs(&guards.document_codecs, document_codecs).map_err(ArtifactAssemblyStoreRegistryError::DocumentCodec)?;
    validate_dialect_migrations(&guards.dialect_migrations, dialect_migrations).map_err(ArtifactAssemblyStoreRegistryError::DialectMigration)
}

/// 📌️ Publishes rows proven safe by `preflight_artifact_assembly_store_registry_guards`.
pub fn commit_artifact_assembly_store_registry_guards(guards: &mut ArtifactAssemblyStoreRegistryGuards<'_>, document_codecs: Vec<ArtifactCodec>, dialect_migrations: Vec<DialectMigration>) {
    for codec in document_codecs {
        guards.document_codecs.entry(codec.schema.clone()).or_insert(codec);
    }
    for migration in dialect_migrations {
        let key = (migration.from.clone(), migration.to.clone());
        guards.dialect_migrations.entry(key).or_insert(migration);
    }
}
